TLM.f("Tempora/Quad3-2",{"officium":"Feria Tertia infra Hebdomadam III in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad3-0","sections":{"Introitus":[{"k":"ref","la":"Ps 16:6, 8"},{"k":"text","la":"Ego clamávi, quóniam exaudísti me, Deus: inclína aurem tuam, et exáudi verba mea: custódi me, Dómine, ut pupíllam óculi: sub umbra alárum tuárum prótege me."},{"k":"ref","la":"Ps 16:1"},{"k":"text","la":"Exáudi, Dómine, justítiam meam: inténde deprecatiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ego clamávi, quóniam exaudísti me, Deus: inclína aurem tuam, et exáudi verba mea: custódi me, Dómine, ut pupíllam óculi: sub umbra alárum tuárum prótege me."}],"Oratio":[{"k":"text","la":"Exáudi nos, omnípotens et miséricors Deus: et continéntiæ salutáris propítius nobis dona concéde."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Regum."},{"k":"ref","la":"4 Reg 4:1-7"},{"k":"text","la":"In diébus illis: Múlier quædam clamábat ad Eliséum Prophétam, dicens: Servus tuus vir meus mórtuus est, et tu nosti, quia servus tuus fuit timens Dóminum: et ecce, créditor venit, ut tollat duos fílios meos ad serviéndum sibi. Cui dixit Eliséus: Quid vis, ut fáciam tibi? Dic mihi, quid habes in domo tua? At illa respóndit: Non hábeo ancílla tua quidquam in domo mea, nisi parum ólei, quo ungar. Cui ait: Vade, pete mútuo ab ómnibus vicínis tuis vasa vácua non pauca. Et ingrédere, et claude óstium tuum, cum intrínsecus fúeris tu et fílii tui: et mitte inde in ómnia vasa hæc: et cum plena fúerint, tolles. Ivit ítaque múlier, et clausit óstium super se et super fílios suos: illi offerébant vasa, et illa infundébat. Cumque plena fuíssent vasa, dixit ad fílium suum: Affer mihi adhuc vas. Et ille respóndit: Non hábeo. Stetítque óleum. Venit autem illa, et indicávit hómini Dei. Et ille: Vade, inquit, vende oleum, et redde creditóri tuo: tu autem et fílii tui vívite de réliquo."}],"Graduale":[{"k":"ref","la":"Ps 18:13-14"},{"k":"text","la":"Ab occúltis meis munda me, Dómine: et ab aliénis parce servo tuo."},{"k":"text","la":"Si mei non fúerint domináti, tunc immaculátus ero: et emundábor a delícto máximo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 18:15-22"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si peccáverit in te frater tuus, vade, et córripe eum inter te et ipsum solum. Si te audíerit, lucrátus eris fratrem tuum. Si autem te non audíerit, ádhibe tecum adhuc unum vel duos, ut in ore duórum vel trium téstium stet omne verbum. Quod si non audíerit eos: dic ecclésiæ. Si autem ecclésiam non audíerit: sit tibi sicut éthnicus et publicánus. Amen, dico vobis, quæcúmque alligavéritis super terram, erunt ligáta et in cœlo: et quæcúmque solvéritis super terram, erunt solúta et in cœlo. Iterum dico vobis, quia si duo ex vobis consénserint super terram, de omni re quamcúmque petíerint, fiet illis a Patre meo, qui in cœlis est. Ubi enim sunt duo vel tres congregáti in nómine meo, ibi sum in médio eórum. Tunc accédens Petrus ad eum, dixit: Dómine, quóties peccábit in me frater meus, et dimíttam ei? usque sépties? Dicit illi Jesus: Non dico tibi usque sépties, sed usque septuágies sépties."}],"Offertorium":[{"k":"ref","la":"Ps 117:16, 17"},{"k":"text","la":"Déxtera Dómini fecit virtútem, déxtera Dómini exaltávit me: non móriar, sed vivam, et narrábo ópera Dómini."}],"Secreta":[{"k":"text","la":"Per hæc véniat, quǽsumus, Dómine, sacraménta nostræ redemptiónis efféctus: qui nos et ab humánis rétrahat semper excéssibus, et ad salutária dona perdúcat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 14:1-2"},{"k":"text","la":"Dómine, quis habitábit in tabernáculo tuo? aut quis requiéscet in monte sancto tuo? Qui ingréditur sine mácula, et operátur justítiam."}],"Postcommunio":[{"k":"text","la":"Sacris, Dómine, mystériis expiáti: et véniam, quǽsumus, consequámur et grátiam."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Tua nos, Dómine, protectióne defénde: et ab omni semper iniquitáte custódi."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f3b6617d3307f439":{"t":"Ps 16, 6 i 8, Ps 16, 1\n(Ps 16, 6 i 8) K tebi vapijem, Bože, jer znam da ćeš me uslišiti. Prikloni uho svoje i čuj riječi moje. Čuvaj me, Gospodine, kao zjenicu oka svoga, pod sjenom krila svojih zaštiti me. (Ps 16, 1) Čuj Gospodine moje pravedne tužbe, usliši moju molitvu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 16, 6 i 8) K tebi vapijem, Bože, jer znam da ćeš me uslišiti. Prikloni uho svoje i čuj riječi moje. Čuvaj me, Gospodine, kao zjenicu oka svoga, pod sjenom krila svojih zaštiti me.","kn":"(P.s. 16, 6, 8). Ja vapijem ik Tebi, jer Ti ceš me uslišati, Bože, čuj, i usliši riječi moje: čuvaj me ao Zjenicu oka, štiti me pod sjenom krila sivojih! (Ps. 16, 1). Usliši, Gospođine, moje pravedne uzdahe cuj molbu moju! Slava Ocu ... Ja vapijem ...","knRef":"Kniewald 1942, str. 154–155 (snimka 78) (OCR)"},"fc000785316063c0":{"t":"<i>Pomolimo se</i>.\nUsliši nas, svemogući i milosrdni Bože, i daj nam milostiv darove spasonosne uzdržljivosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Usliši nas, svemogući i milosrdni Bože, i milostivo nam dozvoli darove spasonosne uzdržliivosti. Po G. n.","knRef":"Kniewald 1942, str. 156–157 (snimka 79) (OCR)"},"165af3d7121b0f70":{"t":"2* Kr 4, 1-4\nČitanje knjige Kraljeva. U one dane neka žena plačući progovori Elizeju: Umro je tvoj sluga, moj muž. A ti znaš da se tvoj sluga bojao Gospodina. Dođe vjerovnik da mi uzme kao robove dva sina! Elizej joj reče: Što tražiš da ti učinim? Kaži što imaš u svojoj kući. Ona odgovori: Tvoja službenica nema u svojoj kući ništa do kapljice ulja kojim se mažem. On joj reče: Idi i posudi od sviju svojih susjeda mnogo praznih posuda. Uđi u kuću, zatvori vrata za sobom, pa kada budeš unutra sa svojim sinovima, lijevaj ulje u svoje sudove. A kada se napune, metni ih na stranu. Žena otiđe, zatvori vrata za sobom i za svojim sinovima, koji su joj dodavali posude, a ona je lijevala. Kada su posude bile pune, reče sinu: Daj mi još jednu posudu!« On odgovori: Nema više. I prestane ulje. Ona dođe i javi Božjem čovjeku. A on joj reče: Idi, prodaj ulje, plati svojem vjerovniku, a ti i tvoji sinovi živite od preostalog. [* Vulgata Sixto-Clementina sadrži četiri knjige o kraljevima, od kojih se prve dvije u drugim novijim izdanjima označavaju kao knjige o Samuelu: I Reg, II Reg, III Reg, IV Reg odgovaraju 1 Sam, 2 Sam, 1 Kr, 2 Kr]","kn":"Čitanje knjige Kraljeva (IV. Kr. 4, 1-7) U ome dame: Žena neka_ povika k Elizeju proroku govoreći: Sluga -tvoj, muž moj, umrije, a ti znaš, da se sluga tvoj bojao Gospodina; a eto dode vjerovnik, M mz uzme u roblje dva sina. Reče joj Elizej: Sto hoces, da ti učinim? Reci mi, što imaš u svojoj kući? A ona odgovori: Službenica tvoja nema ništa u SVOJOJ kući do kapljicu ulja, kojim se mažem A on JOJ i-ece: Idi i pozajmi u svih susjeda svojih mnogo praznih sudova. Pa uđi, i zatvori za sobom vrata, kad budeš unutra sa sinovima svojim: i lijevaj odanle u sve te sudove: i kad se napune, stavi ih na stranu. I žena otiđe i zatvori za sobom vrata 1 za smovima svojim,: omi joj dodavahu sudove, a oma^ lijevaše. A kad se sudovi napuniše, reče sinu svojemu: Dodaj mi još jedan sud. A on odgovori- Nemam. I prestane ulje. A Elizej reče: idi prodaj ulje, 1 plati vjerovniku svome: a ti i sinovi živite od onoga, što preteče.","knRef":"Kniewald 1942, str. 156–157 (snimka 79) (OCR)"},"29e61b8140b9c59e":{"t":"Ps 18, 13-14\nOd tajnih grijeha mojih izbavi me, Gospodine, i od tuđih poštedi slugu svoga. Ako ne zavladaju sa mnom, bit ću nevin i čist od teškoga zlodjela.","kn":"(Ps. 18, 13, 14). Očisti me od tajnih mojih grijeha i brižno čuvaj slugu svoga od oholica. Ne vladaju li oni nada mnom, bit ču nevin i slobodan od teških grijeha.","knRef":"Kniewald 1942, str. 156–157 (snimka 79) (OCR)"},"616a1cf2af91bc69":{"t":"Mt 18, 15-22\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Ako te uvrijedi tvoj brat, pozovi ga i opomeni nasamo. Ako te posluša, dobio si svoga brata. Ako te ne posluša, pozovi još jednoga ili dvojicu, da sve bude pred dvojicom ili trojicom svjedoka. Ako ne posluša ni njih, prijavi Crkvi. Ako ne posluša ni Crkvu, držite ga nevjernikom i javnim grešnikom! Zaista vam kažem: Što god svežete na zemlji, bit će svezano i na nebu, kao i što god razriješite na zemlji, bit će razriješeno i na nebu. Još ponovo vam kažem: Ako dvojica od vas složno mole, nebeski Otac dat će im sve. Jer gdje se dvojica ili trojica sastanu u moje ime ondje sam i ja među njima. Tada Petar pristupi i reče: Gospodine, ako me uvrijedi moj brat koliko puta da mu oprostim? Da li do sedam puta? Isus mu odgovori: Ne kažem ti do sedam, nego do sedamdeset puta sedam."},"a63cb5f96fa870c3":{"t":"Ps 117, 16-17\nDesnica Gospodnja učini čudo, desnica me Gospodnja podiže! Neću umrijeti nego živjeti i naviještati djela Gospodnja.","kn":"(Ps. 117, 16, 17). Desnica Gospodnja poka,za moć, desnica me Gospo'dnja uzvisi: ne ću umrijeti, nego živjeti i kazivat ću djela Gospodnjem","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"462cf4c163bfed5a":{"t":"Sašao nam, molimo, Gospodine, po ovim otajstvima učinak našeg otkupljenja; neka nas on uvijek odvraća od ljudskih zastranjivanja te vodi k spasonosnim darovima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da po ovim tajnama sađručlnak Tašeg otkupljenja,, te nas uv^ek odvraća od ljudskih neumjerenostii 1 privodi spas nosnim darovima, po G. n.","knRef":"Kniewald 1942, str. 156–157 (snimka 79) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"3f518a08cfc35b25":{"t":"Ps 14, 1-2\nGospodine, tko smije stanovati u šatoru tvome? Tko smije počivati na svetoj gori tvojoj? Onaj koji je bez ljage i koji živi pravedno.","kn":"(Ps. 14, 1, 2). Gospodine, tko vati u Tvojem šatoru, tko smije stanovati na Tvojoj svetoj Gori? Onaj, .koji živi bez ljage i koj","knRef":"Kniewald 1942, str. 156–157 (snimka 79) (OCR)"},"6e872ab23c134816":{"t":"<i>Pomolimo se</i>.\nPomireni Gospodine, svetim tajnama molimo, da postignemo i oproštenje i milost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"915ff3a338ffa169":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nBrani nas, Gospodine, svojom zaštitom i uvijek čuvaj od svake opačine.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
